package day2;

public class _2_복습 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		// +, -, *, /(나눗셈), %(나머지연산)
		int num1 = 10 * 5; // 50
		int num2 = 100 % 3; // 1
		
		System.out.println(10 % 2 == 0); // true, 10은 짝수다
		System.out.println(11 % 2 == 0); // false, 11은 홀수다.
		
		// 비교연산자( >, <, >=, <=, ==, != )
		System.out.println(num1 > 30); // true
		System.out.println(num1 >= 50); // true
		System.out.println(num1 == 50); // true
		System.out.println(num1 != 50); // false
		
	}

}
